addGlyphMarginWidget(widget) {
        const widgetData = {
            widget: widget,
            position: widget.getPosition()
        };
        if (this.Db.hasOwnProperty(widget.getId())) {
            console.warn('Overwriting a glyph margin widget with the same id.');
        }
        this.Db[widget.getId()] = widgetData;
        if (this.tb && this.tb.hasRealView) {
            this.tb.view.addGlyphMarginWidget(widgetData);
        }
    }
